<?php $isEdit = $pelanggan !== null; $value = static fn(string $field, mixed $fallback = '') => old($field, $pelanggan[$field] ?? $fallback); ?>
<section class="mb-6"><a href="<?= e($isEdit ? url('/pelanggan/' . rawurlencode($pelanggan['npa'])) : url('/pelanggan')) ?>" class="text-sm font-semibold text-primary hover:underline">← Kembali</a><h1 class="mt-3 text-2xl font-bold text-slate-900"><?= e($title) ?></h1><p class="mt-1 text-sm text-slate-500">Lengkapi informasi pelanggan dengan data yang benar.</p></section>
<form method="post" action="<?= e($action) ?>" class="rounded-2xl bg-white p-5 shadow-card sm:p-7" data-pelanggan-form><?= csrf_field() ?><?php if ($isEdit): ?><input type="hidden" name="_method" value="PUT"><?php endif; ?><div class="grid gap-5 md:grid-cols-2"><div><label for="npa" class="form-label">NPA <span class="text-danger">*</span></label><input id="npa" name="npa" maxlength="20" required <?= $isEdit ? 'readonly' : '' ?> value="<?= e($value('npa')) ?>" class="form-input <?= error('npa') ? 'form-input-error' : '' ?>" placeholder="Contoh: 1201000001"><p class="form-error"><?= e(error('npa') ?? '') ?></p></div><div><label for="nama_pelanggan" class="form-label">Nama Pelanggan <span class="text-danger">*</span></label><input id="nama_pelanggan" name="nama_pelanggan" maxlength="100" required value="<?= e($value('nama_pelanggan')) ?>" class="form-input <?= error('nama_pelanggan') ? 'form-input-error' : '' ?>" placeholder="Nama lengkap pelanggan"><p class="form-error"><?= e(error('nama_pelanggan') ?? '') ?></p></div><div class="md:col-span-2"><label for="alamat" class="form-label">Alamat <span class="text-danger">*</span></label><textarea id="alamat" name="alamat" required rows="3" class="form-input <?= error('alamat') ? 'form-input-error' : '' ?>" placeholder="Alamat lengkap pelanggan"><?= e($value('alamat')) ?></textarea><p class="form-error"><?= e(error('alamat') ?? '') ?></p></div><div><label for="no_telepon" class="form-label">No. Telepon</label><input id="no_telepon" name="no_telepon" maxlength="20" value="<?= e($value('no_telepon')) ?>" class="form-input" placeholder="08xxxxxxxxxx"></div><div><label for="golongan" class="form-label">Golongan</label><input id="golongan" name="golongan" maxlength="10" value="<?= e($value('golongan')) ?>" class="form-input" placeholder="Contoh: R2"></div><div><label for="status" class="form-label">Status <span class="text-danger">*</span></label><select id="status" name="status" required class="form-input <?= error('status') ? 'form-input-error' : '' ?>"><?php foreach (['Aktif','Nonaktif','Putus'] as $option): ?><option value="<?= e($option) ?>" <?= $value('status', 'Aktif') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select><p class="form-error"><?= e(error('status') ?? '') ?></p></div><div id="tanggal-nonaktif-wrap"><label for="tgl_nonaktif" class="form-label">Tanggal Nonaktif <span class="text-danger">*</span></label><input id="tgl_nonaktif" type="date" name="tgl_nonaktif" value="<?= e($value('tgl_nonaktif')) ?>" class="form-input <?= error('tgl_nonaktif') ? 'form-input-error' : '' ?>"><p class="form-error"><?= e(error('tgl_nonaktif') ?? '') ?></p></div></div><div class="mt-7 flex flex-col-reverse justify-end gap-3 border-t border-slate-100 pt-5 sm:flex-row"><a href="<?= e(url('/pelanggan')) ?>" class="rounded-xl border border-slate-200 px-5 py-3 text-center text-sm font-semibold text-slate-600 hover:bg-slate-50">Batal</a><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white hover:bg-primary-dark">Simpan Data Pelanggan</button></div></form>
